-- ----------------------------------------------------------------------------
-- Policies: A coverage agreement. Whether a policy is active is a fact about the policy (ground truth), recorded by the system — not a derived rule.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS policies (
  policy_id                           TEXT                 PRIMARY KEY          -- Stable identifier for the policy.
);
ALTER TABLE policies ADD COLUMN IF NOT EXISTS policyholder_name TEXT;                               -- Name of the policyholder.
ALTER TABLE policies ADD COLUMN IF NOT EXISTS is_active BOOLEAN;                                    -- Ground truth: whether the policy is currently in force. Per R. Ross: being active is a business STATE — a fact about the policy — not a derived business rule. The system's 'Is Active' indicator merely records this fact, so it lives at the leaves, not in a rule.
COMMENT ON TABLE policies IS 'A coverage agreement. Whether a policy is active is a fact about the policy (ground truth), recorded by the system — not a derived rule.';
COMMENT ON COLUMN policies.policy_id IS 'Stable identifier for the policy.';
COMMENT ON COLUMN policies.policyholder_name IS 'Name of the policyholder.';
COMMENT ON COLUMN policies.is_active IS 'Ground truth: whether the policy is currently in force. Per R. Ross: being active is a business STATE — a fact about the policy — not a derived business rule. The system''s ''Is Active'' indicator merely records this fact, so it lives at the leaves, not in a rule.';

-- ----------------------------------------------------------------------------
-- Claimants: A person linked to incidents and (optionally) to claims. Carries a current policy, a favorite color, and a derived incident count.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS claimants (
