COMMENT ON COLUMN claimants.policy IS 'The claimant''s current policy (foreign key to Policies).';

-- ----------------------------------------------------------------------------
-- Incidents: An event or loss that can give rise to a claim. Each incident involves exactly one claimant of record at the incident level.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS incidents (
