-- ----------------------------------------------------------------------------
-- Claims: A request to have an incident evaluated under a policy. Validity and approvability are computed, never entered.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS claims (
  claim_id                            TEXT                 PRIMARY KEY          -- Stable identifier for the claim.
);
ALTER TABLE claims ADD COLUMN IF NOT EXISTS incident TEXT;                                          -- The incident this claim references (exactly one; foreign key to Incidents via IncidentId).
ALTER TABLE claims ADD COLUMN IF NOT EXISTS additional_claimant TEXT;                               -- An optional second claimant linked to the same claim (foreign key to Claimants via ClaimantId).
ALTER TABLE claims ADD COLUMN IF NOT EXISTS is_flagged_for_review BOOLEAN;                          -- Ground truth: whether the claim has been flagged for manual review (e.g., possible fraud). A claim can be valid yet still be held here — which is exactly why 'approvable' is 'only if valid', not 'iff valid'.
COMMENT ON TABLE claims IS 'A request to have an incident evaluated under a policy. Validity and approvability are computed, never entered.';
COMMENT ON COLUMN claims.claim_id IS 'Stable identifier for the claim.';
COMMENT ON COLUMN claims.incident IS 'The incident this claim references (exactly one; foreign key to Incidents via IncidentId).';
COMMENT ON COLUMN claims.additional_claimant IS 'An optional second claimant linked to the same claim (foreign key to Claimants via ClaimantId).';
